-- READ-ONLY authorization preflight. Select the running API database first.
-- Run on the same server and, ideally, with the API database account.
-- No credentials, user rows, hashes or tokens are printed.
SELECT DATABASE() AS selected_database, @@hostname AS server_host, @@port AS server_port,
       CURRENT_USER() AS mysql_account, VERSION() AS mysql_version, 1 AS connection_probe;

SELECT wanted.table_name, IF(t.TABLE_NAME IS NULL,'MISSING','PRESENT') AS table_status
FROM (SELECT 'users' AS table_name UNION ALL SELECT 'roles' AS table_name UNION ALL SELECT 'user_roles' AS table_name UNION ALL SELECT 'permission_modules' AS table_name UNION ALL SELECT 'role_permissions' AS table_name UNION ALL SELECT 'college_settings' AS table_name UNION ALL SELECT 'college_user_mappings' AS table_name UNION ALL SELECT 'colleges' AS table_name UNION ALL SELECT 'user_module_permissions' AS table_name UNION ALL SELECT 'user_academic_year_access' AS table_name UNION ALL SELECT 'academicyears' AS table_name UNION ALL SELECT 'user_access_audits' AS table_name UNION ALL SELECT 'user_access_profiles' AS table_name UNION ALL SELECT 'user_access_invitations' AS table_name) wanted
LEFT JOIN information_schema.TABLES t ON t.TABLE_SCHEMA=DATABASE() AND t.TABLE_NAME=wanted.table_name
ORDER BY wanted.table_name;

SELECT wanted.table_name,wanted.column_name,
       IF(c.COLUMN_NAME IS NULL,'MISSING','PRESENT') AS column_status
FROM (SELECT 'users' AS table_name,'user_id' AS column_name UNION ALL SELECT 'users' AS table_name,'college_id' AS column_name UNION ALL SELECT 'users' AS table_name,'status' AS column_name UNION ALL SELECT 'users' AS table_name,'deleted_at' AS column_name UNION ALL SELECT 'users' AS table_name,'profile_completed' AS column_name UNION ALL SELECT 'users' AS table_name,'access_version' AS column_name UNION ALL SELECT 'users' AS table_name,'must_change_password' AS column_name UNION ALL SELECT 'users' AS table_name,'academic_year_restricted' AS column_name UNION ALL SELECT 'users' AS table_name,'internal_identifier' AS column_name UNION ALL SELECT 'roles' AS table_name,'role_id' AS column_name UNION ALL SELECT 'roles' AS table_name,'college_id' AS column_name UNION ALL SELECT 'roles' AS table_name,'role_code' AS column_name UNION ALL SELECT 'roles' AS table_name,'status' AS column_name UNION ALL SELECT 'roles' AS table_name,'deleted_at' AS column_name UNION ALL SELECT 'user_roles' AS table_name,'user_id' AS column_name UNION ALL SELECT 'user_roles' AS table_name,'role_id' AS column_name UNION ALL SELECT 'user_roles' AS table_name,'status' AS column_name UNION ALL SELECT 'user_roles' AS table_name,'removed_at' AS column_name UNION ALL SELECT 'permission_modules' AS table_name,'module_key' AS column_name UNION ALL SELECT 'permission_modules' AS table_name,'status' AS column_name UNION ALL SELECT 'role_permissions' AS table_name,'role_permission_id' AS column_name UNION ALL SELECT 'role_permissions' AS table_name,'role_id' AS column_name UNION ALL SELECT 'role_permissions' AS table_name,'module_key' AS column_name UNION ALL SELECT 'role_permissions' AS table_name,'college_id' AS column_name UNION ALL SELECT 'role_permissions' AS table_name,'can_view' AS column_name UNION ALL SELECT 'role_permissions' AS table_name,'can_create' AS column_name UNION ALL SELECT 'role_permissions' AS table_name,'can_edit' AS column_name UNION ALL SELECT 'role_permissions' AS table_name,'can_delete' AS column_name UNION ALL SELECT 'role_permissions' AS table_name,'can_export' AS column_name UNION ALL SELECT 'college_settings' AS table_name,'college_setting_id' AS column_name UNION ALL SELECT 'college_settings' AS table_name,'college_id' AS column_name UNION ALL SELECT 'college_settings' AS table_name,'status' AS column_name UNION ALL SELECT 'college_user_mappings' AS table_name,'user_id' AS column_name UNION ALL SELECT 'college_user_mappings' AS table_name,'college_setting_id' AS column_name UNION ALL SELECT 'college_user_mappings' AS table_name,'status' AS column_name UNION ALL SELECT 'college_user_mappings' AS table_name,'removed_at' AS column_name UNION ALL SELECT 'colleges' AS table_name,'college_id' AS column_name UNION ALL SELECT 'colleges' AS table_name,'status' AS column_name UNION ALL SELECT 'colleges' AS table_name,'deleted_at' AS column_name UNION ALL SELECT 'user_module_permissions' AS table_name,'user_id' AS column_name UNION ALL SELECT 'user_module_permissions' AS table_name,'college_id' AS column_name UNION ALL SELECT 'user_module_permissions' AS table_name,'module_key' AS column_name UNION ALL SELECT 'user_module_permissions' AS table_name,'can_view' AS column_name UNION ALL SELECT 'user_module_permissions' AS table_name,'can_create' AS column_name UNION ALL SELECT 'user_module_permissions' AS table_name,'can_edit' AS column_name UNION ALL SELECT 'user_module_permissions' AS table_name,'can_delete' AS column_name UNION ALL SELECT 'user_module_permissions' AS table_name,'can_export' AS column_name UNION ALL SELECT 'user_academic_year_access' AS table_name,'user_id' AS column_name UNION ALL SELECT 'user_academic_year_access' AS table_name,'college_id' AS column_name UNION ALL SELECT 'user_academic_year_access' AS table_name,'academic_year_id' AS column_name UNION ALL SELECT 'academicyears' AS table_name,'academic_year_id' AS column_name UNION ALL SELECT 'academicyears' AS table_name,'college_id' AS column_name UNION ALL SELECT 'academicyears' AS table_name,'deleted_at' AS column_name) wanted
LEFT JOIN information_schema.COLUMNS c ON c.TABLE_SCHEMA=DATABASE()
 AND c.TABLE_NAME=wanted.table_name AND c.COLUMN_NAME=wanted.column_name
ORDER BY wanted.table_name,wanted.column_name;

SET @auth_catalog_sql = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='permission_modules' AND COLUMN_NAME IN ('module_key','status'))=2, 'SELECT wanted.module_key, CASE WHEN pm.module_key IS NULL THEN ''MISSING'' WHEN pm.status<>1 THEN ''DISABLED'' ELSE ''ACTIVE'' END AS catalog_status FROM (SELECT _utf8mb4''dashboard'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''my_profile'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''notifications'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''colleges'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''departments'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''academic_years'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''courses'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''branches'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''semesters'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''sections'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''rooms'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''subjects'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''timetable'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''credits'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''electives'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''materials'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''faculty_directory'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''faculty_attendance'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''faculty_leaves'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''faculty_payroll'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''student_admissions'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''student_profiles'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''student_attendance'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''student_promotions'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''examinations'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''marks'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''results'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''fees'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''library'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''meetings_events'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''placement'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''roles_permissions'' COLLATE utf8mb4_unicode_ci AS module_key UNION ALL SELECT _utf8mb4''academic_settings'' COLLATE utf8mb4_unicode_ci AS module_key) wanted LEFT JOIN permission_modules pm ON pm.module_key COLLATE utf8mb4_unicode_ci=wanted.module_key ORDER BY wanted.module_key', 'SELECT ''Permission catalog table/columns missing; inspect metadata results above.'' AS prerequisite_error');
PREPARE auth_preflight_stmt FROM @auth_catalog_sql;
EXECUTE auth_preflight_stmt;
DEALLOCATE PREPARE auth_preflight_stmt;
